// Shipping binaries generates plan -> build -> execute.
#[test]
fn shipping_binaries_generates_the_build_matrix_workflow() {
    let dir = workspace(1);
    let args = InitArgs {
        workflow: true,
        ..with_targets(&["x86_64-unknown-linux-gnu"])
    };
    assert_eq!(
        run_init_with_runner(
            dir.path(),
            args,
            false,
            vec![],
            false,
            &fake_ls_remote(env!("CARGO_PKG_VERSION")),
        )
        .result
        .unwrap(),
        std::process::ExitCode::SUCCESS
    );
    let workflow = workflow_file(dir.path());
    for expected in [
        "callisto release plan --from-release-commit",
        "include: ${{ fromJSON(needs.plan.outputs.matrix) }}",
        "callisto release execute",
        "with: {mode: version-pr, branch: \"main\"}",
    ] {
        assert!(workflow.contains(expected), "`{expected}` missing:\n{workflow}");
    }
}

// A shape no generated workflow covers skips the question with a note that
// also lands in InitReport.diagnostics for a --format json caller.
#[test]
fn unsupported_workspace_skips_workflow_generation_with_a_json_diagnostic() {

use std::path::Path;

use callisto_model::{CommandError, CommandOutput};

use super::*;
use crate::commands::release::tests::RealGitRunner;
use crate::IgnoreWalkLocator;

pub(in crate::commands::init) const ORIGIN: &str = "https://github.com/example/tools.git";

fn git(root: &Path, args: &[&str]) {
    let status = std::process::Command::new("git")
        .args(args)
        .current_dir(root)
        .status()
        .unwrap();
    assert!(status.success(), "git {args:?}");
}

pub(in crate::commands::init) fn repo(files: &[(&str, &str)], origin: Option<&str>) -> tempfile::TempDir {
    let dir = tempfile::tempdir().unwrap();
    for (path, content) in files {
        let path = dir.path().join(path);
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        std::fs::write(path, content).unwrap();
    }
    callisto_fixtures::git::init_repo(dir.path());
    if let Some(origin) = origin {
        git(dir.path(), &["remote", "add", "origin", origin]);
    }
    git(dir.path(), &["add", "."]);
    git(dir.path(), &["commit", "-q", "-m", "fixture"]);
    dir
}

fn tag(root: &Path, name: &str) {
    git(root, &["tag", name]);
}

fn cargo(name: &str, version: &str) -> String {
    format!("[package]\nname = \"{name}\"\nversion = \"{version}\"\nedition = \"2021\"\ndescription = \"t\"\nlicense = \"MIT\"\n")
}

/// A Cargo binary `app`, a Cargo library `core`, and an npm library `web`.
fn workspace() -> tempfile::TempDir {
    repo(
        &[
            (
                "Cargo.toml",
                "[workspace]\nmembers = [\"app\", \"core\"]\nresolver = \"2\"\n",
            ),
            ("app/Cargo.toml", &cargo("app", "1.0.0")),
            ("app/src/main.rs", "fn main() {}\n"),
            ("core/Cargo.toml", &cargo("core", "1.0.0")),
            ("core/src/lib.rs", "\n"),
            ("web/package.json", r#"{"name":"web","version":"2.0.0"}"#),
        ],
        Some(ORIGIN),
    )
}

